(function () {
  "use strict";
  // Layer JS loads on every page: it does nothing without a workbench.
  var workbench = document.querySelector("[data-studio-workbench]");
  if (!workbench) {
    return;
  }
  // studio.js (studio:studio, order 0) runs first and gives the API.
  var S = window.ScrudStudio;
  if (!S) return;

  // The preview pane's controls, and the inspector under the preview. Each
  // control sets its key of the URL state and submits the preview again. A
  // click in the preview (the bridge's select message) on a node of the
  // previewed resource is explained (`explain`), as text; on a working
  // branch the inspector offers "Edit this component" (the winning
  // component, opened from the items tree) and "New rule for this node"
  // (the bootstrap studio's form, from `options`, posted to
  // `new_component`).
  var CONTROLS = ["type", "mode", "context", "scope", "instance", "pinned"];
  var BUILTIN = "scrud:";
  var TEMPLATE = "<span>{{ value }}</span>";
  var MAX_TEXT = 500;
  var HINT = "Click a part of the preview to inspect it.";
  var RESTORED = "The template you typed for this node before is back.";
  var PINNED_NOTE =
    "The preview is pinned at the branching point, but a new rule is made on" +
    " the live branch. Unpin the preview to make one.";
  var explainBox = workbench.querySelector("[data-studio-explain]");
  // None on a published T: the workbench has no place for it.
  var newRule = S.published ? null : workbench.querySelector("[data-studio-new-rule]");
  // The selected node's pointer ("" is the resource itself), or null.
  var selected = null;
  // The latest explain, and the latest options or new rule, by number: a
  // slow answer to an older one is dropped.
  var explainSeq = 0;
  var formSeq = 0;
  // What the new rule form was built from: {matches, inside, pointer, state}.
  var offered = null;
  // The explanation shown, {seq, data, state}, or null: shown again when the
  // items pane swaps, so that "Edit this component" follows the tree.
  var shown = null;
  // Templates typed in a new rule form that closed before a Create from it
  // succeeded, by node (nodeKey): its form opens with it again.
  var kept = {};

  // ---- text in the page ---------------------------------------------------

  function empty(node) {
    while (node.firstChild) node.removeChild(node.firstChild);
  }

  // A new element with `text` as its text (never markup).
  function append(parent, tag, className, text) {
    var node = document.createElement(tag);
    if (className) node.setAttribute("class", className);
    if (text !== undefined) node.textContent = text;
    parent.appendChild(node);
    return node;
  }

  function show(text) {
    shown = null;
    if (!explainBox) return;
    empty(explainBox);
    append(explainBox, "p", "studio-hint", text);
  }

  // ---- the preview's parameters -------------------------------------------

  function isPinned(state) {
    return state.pinned === "1" || state.pinned === "true";
  }

  function scopeOf(state) {
    return String(state.scope || "")
      .split(/[\s,]+/)
      .filter(Boolean)
      .join(" ");
  }

  // The URL of `template` (explain or options) for the node at `pointer`,
  // with the preview's parameters: T (its snapshot when pinned), mode,
  // scope, data context and instance. URLSearchParams encodes every
  // reserved character, so the server reads the exact pointer back.
  function nodeUrl(template, state, pointer) {
    var params = new URLSearchParams();
    params.set("branch", isPinned(state) ? S.branch + "@pinned" : S.branch);
    params.set("mode", state.mode || "view");
    params.set("scope", scopeOf(state));
    params.set("context", state.context || "");
    if (state.instance) params.set("instance", state.instance);
    params.set("pointer", pointer);
    return template.replace("{slug}", encodeURIComponent(state.type)) + "?" + params.toString();
  }

  // Whether `href` (a select's data-scrud-href) is the previewed resource's
  // own frame: the type's sample (the strip's `sample` endpoint), or with
  // an instance its detail (".../<slug>/<instance>/"), a path as the
  // preview renders it (a list's items have absolute URLs). Any other frame
  // is an embedded resource, whose pointers are relative to it.
  function ownFrame(href, state) {
    if (typeof href !== "string" || href.charAt(0) !== "/" || href.charAt(1) === "/") {
      return false;
    }
    var path = href.split("#")[0].split("?")[0];
    if (state.instance) {
      var parts = path.split("/");
      if (parts.length < 4 || parts[parts.length - 1] !== "") return false;
      try {
        return (
          decodeURIComponent(parts[parts.length - 3]) === state.type &&
          decodeURIComponent(parts[parts.length - 2]) === state.instance
        );
      } catch (e) {
        return false;
      }
    }
    var where = S.endpoints();
    if (!where || typeof where.sample !== "string") return false;
    return path === where.sample.replace("{slug}", encodeURIComponent(state.type));
  }

  // ---- requests -----------------------------------------------------------

  function headers(extra) {
    var found = { Accept: "application/json" };
    if (S.safe()) found["Scrud-UI-Safe"] = "1";
    Object.keys(extra || {}).forEach(function (name) {
      found[name] = extra[name];
    });
    return found;
  }

  // A request as the user (`fetch`, same origin): resolves to {ok: true,
  // data} or {ok: false, text}, the server's error text (ScrudStudio's
  // errorText). Null without fetch.
  function send(url, init) {
    if (typeof fetch !== "function") return null;
    init.credentials = "same-origin";
    return fetch(url, init).then(
      function (response) {
        return response.text().then(function (body) {
          if (response.ok) {
            try {
              return { ok: true, data: JSON.parse(body) };
            } catch (e) {
              return { ok: false, text: "The answer could not be read." };
            }
          }
          return {
            ok: false,
            text: S.errorText({
              status: response.status,
              responseText: body,
              getResponseHeader: function (name) {
                return response.headers.get(name);
              }
            })
          };
        });
      },
      function () {
        return { ok: false, text: S.errorText({ status: 0 }) };
      }
    );
  }

  // ---- the explanation ----------------------------------------------------

  function source(rule) {
    var text = "stylesheet " + String(rule.stylesheet);
    if (rule.branch) text += " on " + String(rule.branch);
    if (rule.applies_to) text += ", applies to " + String(rule.applies_to);
    return text;
  }

  // A rule as text: what it selects and chooses, from where, and how it
  // fared; a rule the user may not read, its rank and outcome only.
  function describeRule(rule) {
    var outcome = String(rule.outcome);
    if (rule.readable !== true) {
      return outcome + ": a rule you can't read (rank " + JSON.stringify(rule.rank) + ")";
    }
    return (
      outcome +
      ": " +
      String(rule.selector) +
      " -> " +
      String(rule.component) +
      " (" +
      source(rule) +
      ")"
    );
  }

  function verdict(winner, fallback) {
    if (winner && winner.readable === true) {
      return (
        "Component " +
        String(winner.component) +
        ", chosen by " +
        String(winner.selector) +
        " (" +
        source(winner) +
        ")."
      );
    }
    if (winner) return "Its component is chosen by a rule you can't read.";
    return "No rule chose a component: it gets the built-in " + String(fallback) + ".";
  }

  function fact(list, name, values) {
    append(list, "dt", "", name);
    var found = Array.isArray(values) ? values.map(String) : [];
    append(list, "dd", "", found.length ? found.join(" ") : "none");
  }

  // The tree's entry of the winning component, when it is a stored one the
  // user may read; else null (no "Edit this component").
  function winnerEntry(winner) {
    if (!winner || winner.readable !== true || typeof winner.component !== "string") {
      return null;
    }
    if (winner.component.indexOf(BUILTIN) === 0) return null;
    return S.entryFor(S.itemKey({ kind: "component", name: winner.component }));
  }

  function render(data, state) {
    if (!explainBox) return;
    empty(explainBox);
    var found = data && typeof data === "object" ? data : {};
    var pointer = typeof found.pointer === "string" ? found.pointer : selected;
    append(
      explainBox,
      "p",
      "studio-inspector-node",
      "Node " + (pointer === "" ? "(the resource)" : pointer)
    );
    var facts = append(explainBox, "dl", "studio-facts");
    fact(facts, "Terms", found.terms);
    fact(facts, "Scope", found.scope);
    var rules = Array.isArray(found.rules) ? found.rules : [];
    var winner = typeof found.winner === "number" ? rules[found.winner] : null;
    if (!winner || typeof winner !== "object") winner = null;
    append(explainBox, "p", "studio-verdict", verdict(winner, found.fallback));
    if (rules.length) {
      var list = append(explainBox, "ol", "studio-explain-rules");
      rules.forEach(function (rule) {
        append(list, "li", "", describeRule(rule && typeof rule === "object" ? rule : {}));
      });
    }
    // A published T is read-only: no action at all.
    if (S.published) return;
    var actions = append(explainBox, "div", "studio-inspector-actions");
    if (winnerEntry(winner)) {
      var edit = append(actions, "button", "studio-edit-component", "Edit this component");
      edit.setAttribute("type", "button");
      edit.setAttribute("data-studio-edit", winner.component);
    }
    if (!newRule) return;
    var create = append(actions, "button", "studio-new-rule-open", "New rule for this node");
    create.setAttribute("type", "button");
    create.setAttribute("data-studio-new", "");
    if (isPinned(state)) {
      create.setAttribute("disabled", "");
      append(actions, "p", "studio-hint", PINNED_NOTE);
    }
  }

  // Ask `explain` for the selected node, and show its answer.
  function explain() {
    var state = S.state();
    var where = S.endpoints();
    if (selected === null || !state.type || !explainBox) return;
    if (!where || typeof where.explain !== "string") return;
    var mine = ++explainSeq;
    show("Explaining " + (selected === "" ? "the resource" : selected) + "...");
    var sent = send(nodeUrl(where.explain, state, selected), {
      method: "GET",
      headers: headers()
    });
    if (!sent) return;
    sent.then(function (got) {
      if (mine !== explainSeq) return;
      if (got.ok) {
        shown = { seq: mine, data: got.data, state: state };
        render(got.data, state);
      }
      else show(got.text);
    });
  }

  function select(pointer) {
    selected = pointer;
    // "" (the resource itself) is no key in the URL.
    S.setState({ pointer: pointer });
    closeForm();
    explain();
  }

  // The bridge's select message: only from the preview's own window, and
  // only this shape (the branch's scripts can post too).
  window.addEventListener("message", function (evt) {
    if (!S.fromPreview(evt)) return;
    var data = evt.data;
    if (!data || typeof data !== "object" || data.type !== "scrud-preview:select") return;
    if (typeof data.pointer !== "string") return;
    var state = S.state();
    if (!state.type) return;
    if (ownFrame(data.href, state)) {
      select(data.pointer);
      return;
    }
    // A node of an embedded resource: its pointer is not one of this
    // preview's, so it is not explained.
    selected = null;
    explainSeq++;
    S.setState({ pointer: null });
    closeForm();
    show(
      typeof data.href === "string"
        ? ("Inside embedded resource " + data.href).slice(0, MAX_TEXT)
        : "Not inside the previewed resource."
    );
  });

  // ---- "Edit this component" ----------------------------------------------

  // The tree's entry opens in the editor (as a click on it would), the
  // editor pane shown if it was collapsed.
  function editComponent(name) {
    var entry = S.entryFor(S.itemKey({ kind: "component", name: name }));
    if (!entry) return;
    S.expand("editor");
    S.open(entry);
  }

  // ---- "New rule for this node" -------------------------------------------

  function nodeKey(state, pointer) {
    return String(state.type) + " " + pointer;
  }

  function nodeName(pointer) {
    return pointer === "" ? "the resource" : pointer;
  }

  // The template typed in the form, when it is neither the default nor
  // what a Create from the form made; else null.
  function typedTemplate() {
    var template = newField("template");
    if (!offered || !template) return null;
    var value = String(template.value);
    return value === TEMPLATE || value === offered.created ? null : value;
  }

  // Closing the form keeps what was typed in it for its node.
  function closeForm() {
    if (offered) {
      var key = nodeKey(offered.state, offered.pointer);
      var typed = typedTemplate();
      if (typed !== null) kept[key] = typed;
      else delete kept[key];
    }
    formSeq++;
    offered = null;
    if (!newRule) return;
    empty(newRule);
    newRule.setAttribute("hidden", "");
  }

  function field(label, tag, name) {
    var holder = append(newRule, "label", "studio-control", label + " ");
    var control = document.createElement(tag);
    control.setAttribute("data-studio-new-field", name);
    holder.appendChild(control);
    return control;
  }

  function option(select, value, text) {
    var node = append(select, "option", "", text);
    node.setAttribute("value", value);
    return node;
  }

  function newField(name) {
    return newRule ? newRule.querySelector('[data-studio-new-field="' + name + '"]') : null;
  }

  // A broad match's label for the chosen data context: "every string in
  // acme on this branch".
  function labelMatches() {
    var match = newField("match");
    var applies = newField("applies_to");
    if (!offered || !match || !applies) return;
    var context = applies.value;
    var suffix = " on this branch";
    var options = match.querySelectorAll("option");
    offered.matches.forEach(function (offer, index) {
      var label = String(offer.label);
      var broad = offer.broad === true && context && label.slice(-suffix.length) === suffix;
      if (broad) label = label.slice(0, -suffix.length) + " in " + context + suffix;
      if (options[index]) options[index].textContent = label;
    });
  }

  function insideText(inside) {
    return (
      "Inside this type: give property " +
      String(inside.property) +
      " the scope " +
      String(inside.scope) +
      (inside.creates_root
        ? " in a new Jinja copy of " + String(inside.root_component) + " on this branch"
        : " in " + String(inside.root_component)) +
      ", and select inside it"
    );
  }

  // The bootstrap studio's form, from the options for the node.
  function buildForm(data, state, pointer) {
    var found = data && typeof data === "object" ? data : {};
    var matches = (Array.isArray(found.matches) ? found.matches : []).filter(function (m) {
      return m && typeof m === "object" && typeof m.select === "string";
    });
    empty(newRule);
    append(newRule, "h4", "studio-new-rule-title", "New rule for this node");
    if (!matches.length) {
      append(newRule, "p", "studio-hint", "No rule can be made for this node.");
      return;
    }
    var inside = found.inside_type && typeof found.inside_type === "object";
    offered = {
      matches: matches,
      inside: inside ? found.inside_type : null,
      pointer: pointer,
      state: state
    };
    var match = field("Match", "select", "match");
    matches.forEach(function (m) {
      option(match, m.select, String(m.label));
    });
    match.value = matches[0].select;
    if (offered.inside) {
      var holder = append(newRule, "label", "studio-control");
      var box = document.createElement("input");
      box.setAttribute("type", "checkbox");
      box.setAttribute("data-studio-new-field", "inside_type");
      holder.appendChild(box);
      append(holder, "span", "", insideText(offered.inside));
    }
    var where = field("Where", "select", "where");
    option(where, "", "anywhere");
    (Array.isArray(found.where) ? found.where : []).forEach(function (scope) {
      option(where, String(scope), "inside " + String(scope));
    });
    where.value = "";
    var contexts = Array.isArray(found.applies_to) && found.applies_to.length
      ? found.applies_to.map(String)
      : [""];
    var applies = field("Applies to", "select", "applies_to");
    contexts.forEach(function (context) {
      option(applies, context, context ? "data in " + context : "every context");
    });
    applies.value = contexts[0];
    if (typeof found.name === "string" && found.name) {
      append(newRule, "p", "studio-hint", "It will be called " + found.name + ".");
    }
    var template = field("Template (Jinja)", "textarea", "template");
    template.setAttribute("rows", "6");
    template.setAttribute("spellcheck", "false");
    var key = nodeKey(state, pointer);
    template.value = TEMPLATE;
    if (typeof kept[key] === "string") {
      template.value = kept[key];
      delete kept[key];
      append(newRule, "p", "studio-hint", RESTORED);
    }
    var create = append(newRule, "button", "studio-new-rule-create", "Create");
    create.setAttribute("type", "button");
    create.setAttribute("data-studio-new-create", "");
    var result = append(newRule, "p", "studio-result", "");
    result.setAttribute("role", "status");
    result.setAttribute("data-studio-new-result", "");
    labelMatches();
  }

  // Off on a published T and while the preview is pinned.
  function openForm() {
    var state = S.state();
    var where = S.endpoints();
    if (!newRule || S.published || isPinned(state) || selected === null) return;
    if (!state.type || !where || typeof where.options !== "string") return;
    closeForm();
    var mine = formSeq;
    var pointer = selected;
    append(newRule, "p", "studio-hint", "Loading the options...");
    newRule.removeAttribute("hidden");
    var sent = send(nodeUrl(where.options, state, pointer), {
      method: "GET",
      headers: headers()
    });
    if (!sent) return;
    sent.then(function (got) {
      if (mine !== formSeq) return;
      if (got.ok) {
        buildForm(got.data, state, pointer);
        return;
      }
      empty(newRule);
      append(newRule, "p", "studio-result", got.text);
    });
  }

  // Whether the new rule wins for the node, and if not, what beats it.
  function createdText(data) {
    var found = data && typeof data === "object" ? data : {};
    var made = (Array.isArray(found.written) ? found.written : []).filter(function (w) {
      return w && w.kind === "component";
    });
    var name = made.length ? String(made[made.length - 1].name) : "the component";
    if (found.wins === true) return "Created " + name + ". Its rule now wins for this node.";
    var explanation = found.explanation && typeof found.explanation === "object"
      ? found.explanation
      : {};
    var rules = Array.isArray(explanation.rules) ? explanation.rules : [];
    var mine = rules.filter(function (r) {
      return r && r.readable === true && r.component === name;
    })[0];
    var winner = typeof explanation.winner === "number" ? rules[explanation.winner] : null;
    var said = "Created " + name + ". Its rule does not win for this node";
    if (mine) said += " (" + String(mine.outcome) + ")";
    if (winner && winner.readable === true) {
      said += ": it loses to " + String(winner.selector) + " -> " + String(winner.component);
    }
    return said + ".";
  }

  // POST the form to `new_component` as JSON, with the CSRF token. On 201
  // the items, the strip, the preview and the explanation are fetched
  // again; a refusal shows the server's text. The answer goes to the form
  // it was sent from, or, when that form has closed meanwhile, to the
  // workbench's notice.
  function createRule() {
    var where = S.endpoints();
    if (!newRule || !offered || S.published || isPinned(S.state())) return;
    if (!where || typeof where.new_component !== "string") return;
    var state = offered.state;
    var value = function (name) {
      var found = newField(name);
      return found ? String(found.value) : "";
    };
    var inside = newField("inside_type");
    var body = {
      branch: S.branch,
      slug: state.type,
      mode: state.mode || "view",
      scope: scopeOf(state),
      context: state.context || "",
      pointer: offered.pointer,
      match: value("match"),
      inside_type: !!(offered.inside && inside && inside.checked),
      where: value("where"),
      applies_to: value("applies_to"),
      template: value("template")
    };
    if (state.instance) body.instance = state.instance;
    var mine = formSeq;
    var form = offered;
    var key = nodeKey(state, offered.pointer);
    var said = "New rule for " + nodeName(offered.pointer) + ": ";
    var sent = send(where.new_component, {
      method: "POST",
      headers: headers({ "Content-Type": "application/json", "X-CSRFToken": S.csrfToken() }),
      body: JSON.stringify(body)
    });
    if (!sent) return;
    sent.then(function (got) {
      // The form it was sent from, if it is still shown.
      var result = mine === formSeq ? newRule.querySelector("[data-studio-new-result]") : null;
      if (!got.ok) {
        if (result) result.textContent = got.text;
        else S.notify(said + got.text);
        return;
      }
      // Made: what was typed for the node is no longer unsaved.
      delete kept[key];
      if (result) {
        form.created = body.template;
        result.textContent = createdText(got.data);
      } else {
        S.notify(said + createdText(got.data));
      }
      S.refresh("items");
      S.refresh("status");
      S.submitPreview({});
      explain();
    });
  }

  // ---- events -------------------------------------------------------------

  // The items tree was fetched again (after a new rule, at the same time as
  // the explanation): the explanation shown is rendered again, so "Edit
  // this component" is offered for a winner the tree lists now, whichever
  // answered first.
  document.addEventListener("htmx:afterSwap", function (evt) {
    var items = workbench.querySelector('[data-studio-embed="items"]');
    if (!items || evt.target !== items) return;
    if (shown && shown.seq === explainSeq) render(shown.data, shown.state);
  });

  // A write from the workbench succeeded (studio.js's "studio:written",
  // with the items, the strip and the preview fetched again): what chose
  // the selected node's component may have changed, so it is explained
  // again. An answer to an explain sent before is dropped (explainSeq).
  workbench.addEventListener("studio:written", function () {
    if (selected !== null) explain();
  });

  workbench.addEventListener("click", function (evt) {
    var target = evt.target;
    if (!target || typeof target.closest !== "function" || !explainBox) return;
    var edit = target.closest("[data-studio-edit]");
    if (edit && explainBox.contains(edit)) {
      if (!S.published) editComponent(edit.getAttribute("data-studio-edit"));
      return;
    }
    var open = target.closest("[data-studio-new]");
    if (open && explainBox.contains(open)) {
      if (!open.hasAttribute("disabled")) openForm();
      return;
    }
    var create = target.closest("[data-studio-new-create]");
    if (create && newRule && newRule.contains(create)) createRule();
  });

  // A control sets its key of the URL state and submits the preview again
  // (a new type: setState does, with the strip). The selected node was of
  // the old preview: it is cleared.
  function changeControl(name, element) {
    var value =
      name === "pinned" ? (element.checked ? "1" : null) : String(element.value || "").trim();
    var changes = { pointer: null };
    changes[name] = value;
    var before = S.state().type;
    selected = null;
    explainSeq++;
    closeForm();
    show(HINT);
    var after = S.setState(changes);
    if (after.type === before) S.submitPreview({});
  }

  workbench.addEventListener("change", function (evt) {
    var target = evt.target;
    if (!target || typeof target.getAttribute !== "function") return;
    if (newRule && newRule.contains(target)) {
      if (target.getAttribute("data-studio-new-field") === "applies_to") labelMatches();
      return;
    }
    var name = target.getAttribute("data-studio-control");
    if (name && CONTROLS.indexOf(name) >= 0) changeControl(name, target);
  });

  // ---- start --------------------------------------------------------------

  // The controls show the URL state (a component can't read the query).
  function showState() {
    var state = S.state();
    CONTROLS.forEach(function (name) {
      var element = workbench.querySelector('[data-studio-control="' + name + '"]');
      if (!element) return;
      if (name === "pinned") element.checked = isPinned(state);
      else if (name === "mode") element.value = state.mode || "view";
      else element.value = state[name] || "";
    });
  }

  // A template typed and not created is unsaved work: the workbench is not
  // reloaded under it.
  S.watchUnsaved(function () {
    return typedTemplate() !== null || Object.keys(kept).length > 0;
  });

  showState();
  var initial = S.state();
  if (initial.type && typeof initial.pointer === "string") {
    selected = initial.pointer;
    explain();
  }
})();
